<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('production.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'production_jobs');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='create'){$pdo->prepare('INSERT INTO production_jobs(production_code,project_id,status,priority,assigned_supervisor,scheduled_start,notes,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([op_code('PROD'),fint('project_id'),'queued',fpost('priority','normal'),fint('assigned_supervisor'),fpost('scheduled_start')?:null,fpost('notes')?:null,$staff['id']]);flash('success','Production job created.');}elseif($a==='status'){$pdo->prepare('UPDATE production_jobs SET status=?,actual_start=IF(?="cutting" AND actual_start IS NULL,NOW(),actual_start),actual_finish=IF(?="completed",NOW(),actual_finish) WHERE id=?')->execute([fpost('status'),fpost('status'),fpost('status'),fint('id')]);flash('success','Production stage updated.');}staff_redirect('staff/pages/production.php');}
$projects=project_options($pdo);$staffs=staff_options($pdo);$rows=db_rows($pdo,'SELECT j.*,p.project_code,p.name project_name,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) supervisor FROM production_jobs j JOIN projects p ON p.id=j.project_id LEFT JOIN staff s ON s.id=j.assigned_supervisor ORDER BY FIELD(j.priority,"urgent","high","normal","low"),j.updated_at DESC');$stages=['queued','cutting','edging','assembly','finishing','qc','ready_for_installation','completed','on_hold'];$pageTitle='Production Board';require __DIR__.'/../../includes/staff/header.php';module_head('Workshop','Production Board','Move each job through cutting, edging, assembly, finishing and QC.');?>
<section class="staff-panel"><form method="post" class="mini-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Project<select name="project_id" required><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Priority<select name="priority"><option>normal</option><option>high</option><option>urgent</option><option>low</option></select></label><label>Supervisor<select name="assigned_supervisor"><option value="">Unassigned</option><?php foreach($staffs as $s):?><option value="<?=$s['id']?>"><?=hopt($s['first_name'],$s['last_name'])?></option><?php endforeach?></select></label><label>Start<input type="datetime-local" name="scheduled_start"></label><button class="btn primary">Queue project</button></form></section><div class="board"><?php foreach($stages as $stage):?><section class="board-col"><h3><?=h(ucwords(str_replace('_',' ',$stage)))?></h3><?php foreach(array_filter($rows,fn($r)=>$r['status']===$stage) as $r):?><div class="board-card"><b><?=h($r['project_code'])?></b><p><?=h($r['project_name'])?></p><small><?=h($r['priority'])?> · <?=h($r['supervisor']?:'Unassigned')?></small><form method="post" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach($stages as $s):?><option <?=$s===$r['status']?'selected':''?>><?=$s?></option><?php endforeach?></select><button class="btn">Move</button></form></div><?php endforeach?></section><?php endforeach?></div><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>